// Chama a Edge Function da Yampi para um cupom/mês. Cache em memória pra não repetir chamadas.
const _yampiCache = {};
function buscarVendasYampi(cupomCode, ym, descontoCupomPct, comissaoPct){
  const key = [cupomCode, ym, descontoCupomPct, comissaoPct].join('|');
  if(!_yampiCache[key]){
    _yampiCache[key] = sb.functions.invoke('yampi-sync-atleta', {
      body: { alias: YAMPI_ALIAS, cupomCode, ym, descontoCupomPct: descontoCupomPct||10, comissaoPct: comissaoPct||10 }
    }).then(({ data, error })=>{
      if(error) throw error;
      if(data && data.error) throw new Error(data.error);
      return data;
    }).catch(err=>{ delete _yampiCache[key]; throw err; });
  }
  return _yampiCache[key];
}
function vendaParaLinha(d){ return d ? { valor_vendido:d.valorVendido, comissao_mes:d.comissaoMes, numero_pedidos:d.numeroPedidos } : null; }

// Carrega o mês selecionado E o mês anterior (dados reais da Yampi) pro "vs. mês anterior"
async function carregarDashboardVendas(cupomCode, ym, descontoCupomPct, comissaoPct, containerId, opts){
  const container = document.getElementById(containerId);
  container.innerHTML = `<div class="panel"><div style="color:var(--muted); font-size:12px;"><span class="loader" style="border-top-color:var(--orange); border-color:rgba(0,0,0,0.1);"></span> Carregando pedidos da Yampi...</div></div>`;
  try{
    const [data, prevData] = await Promise.all([
      buscarVendasYampi(cupomCode, ym, descontoCupomPct, comissaoPct),
      buscarVendasYampi(cupomCode, addMonths(ym, -1), descontoCupomPct, comissaoPct).catch(err=>{ console.warn('mês anterior', err); return null; }),
    ]);
    container.innerHTML = dashboardVendasHtml(data, Object.assign({cupom:cupomCode, ym, descontoPct:descontoCupomPct, comissaoPct}, opts||{}, {prev: vendaParaLinha(prevData)}));
    return data;
  }catch(err){
    console.error(err);
    container.innerHTML = `<div class="panel"><div style="color:var(--red); font-size:12.5px;">Falhou: ${escHtml(err.message||err)}</div></div>`;
    return null;
  }
}

// Barras mensais a partir da tabela vendas_mensais (últimos N meses até `ateYM`)
function barrasMensaisHtml(rows, ateYM, n, campo){
  campo = campo || 'valor_vendido';
  const porYM = {}; (rows||[]).forEach(r=>{ porYM[r.ym] = (porYM[r.ym]||0) + Number(r[campo]||0); });
  const data = [];
  for(let i=n-1; i>=0; i--){
    const ym = addMonths(ateYM, -i), v = porYM[ym]||0, prevV = porYM[addMonths(ym,-1)]||0;
    const pct = prevV ? ((v-prevV)/prevV*100) : null;
    const qtd = campo === 'numero_pedidos';
    data.push({label:shortMonth(ym), value:v, highlight: ym===ateYM, tip:`${qtd ? `${fmtNum(v)} pedidos` : fmtBRL(v)}|${fmtMonthLabel(ym)}`,
      badge: pct==null ? (qtd ? fmtNum(v) : `R$ ${compactNum(v)}`) : `${pct>=0?'+':''}${pct.toFixed(1).replace('.',',')}%`});
  }
  return pillBarChartHtml(data, {ariaLabel: campo==='numero_pedidos' ? 'Pedidos por mês' : 'Vendas por mês'});
}
